import{z as s,x as E,o as t,c as A,q as r,j as n,D as e,d as l,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"FX 波动率报价 ATM / RR / BF","description":"","frontmatter":{"title":"FX 波动率报价 ATM / RR / BF","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fx-vol-quotes.md","filePath":"quant/fx-vol-quotes.md","lastUpdated":1791413859000}'),p={name:"quant/fx-vol-quotes.md"};function m(F,a,T,d,u,R){const i=E("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="fx-波动率报价-atm-rr-bf" tabindex="-1">FX 波动率报价 ATM / RR / BF <a class="header-anchor" href="#fx-波动率报价-atm-rr-bf" aria-label="Permalink to &quot;FX 波动率报价 ATM / RR / BF&quot;">​</a></h1><div class="epigraph"><p>外汇微笑不按执行价报，而按 ATM、风险反转与蝶式三个可交易结构报；它们近似水平、倾斜与弯曲。</p><footer>—— Malz, Estimating the Probability Distribution of the Future Exchange Rate from Option Prices, Journal of Derivatives, 1997；Clark, Foreign Exchange Option Pricing</footer></div><p><a href="/quant/garman-kohlhagen">上一课</a>给出无微笑的 GK。本课把 <a href="/quant/quoting-conventions">报价惯例</a> 在 FX 上展开：ATM vol、25Δ risk reversal、25Δ butterfly。缺口是这三件事如何还原出 \\(K\\mapsto\\sigma(K)\\)，以及 Vanna–Volga 一类快捷法与完整曲面校准的分工。后课 FX 障碍依赖翼部，不能只盯 ATM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>做市商报 \\(\\sigma_{\\mathrm{ATM}}\\)、\\(\\mathrm{RR}_{25}=\\sigma_{25c}-\\sigma_{25p}\\)、\\(\\mathrm{BF}_{25}=\\tfrac12(\\sigma_{25c}+\\sigma_{25p})-\\sigma_{\\mathrm{ATM}}\\)（定义有变体）。三个数交易的是三个流动性最好的组合，不是三个独立执行价。问题是反解 \\(\\sigma_{25c},\\sigma_{25p}\\) 再插值整张微笑：Delta 与 \\(K\\) 的映射依赖 vol 自身，方程是隐式的，要迭代。用股权那套「按 \\(K\\) 扫隐波」去读 FX 经纪人屏幕，会对不上任何一笔成交。</p>',5)),(t(),n(o,null,{default:e(()=>[B(i,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%B1%8F%E5%B9%95%E6%8A%A5%E4%BB%B7%E4%B8%89%E5%85%83%E7%BB%84%3A%3Cbr%2F%3EATM%20%2F%20RR25%20%2F%20BF25%22%5D%20--%3E%20R%5B%22RR%20%3D%20%E7%9C%8B%E6%B6%A8%E5%87%8F%E7%9C%8B%E8%B7%8C%3Cbr%2F%3E%E5%AE%9A%E5%B7%A6%E5%8F%B3%E7%BF%BC%E5%B7%AE%22%5D%0A%20%20A%20--%3E%20B%5B%22BF%20%3D%20%E7%BF%BC%E5%B9%B3%E5%9D%87%E5%87%8F%20ATM%3Cbr%2F%3E%E5%AE%9A%E4%B8%A4%E7%BF%BC%E9%AB%98%E5%BA%A6%22%5D%0A%20%20R%20--%3E%20C%5B%22%CF%8325c%20%3D%20ATM%20%2B%20BF%20%2B%20RR%2F2%22%5D%0A%20%20B%20--%3E%20C%0A%20%20R%20--%3E%20P%5B%22%CF%8325p%20%3D%20ATM%20%2B%20BF%20%E2%88%92%20RR%2F2%22%5D%0A%20%20B%20--%3E%20P%0A%20%20C%20--%3E%20S%5B%22ATM%20%2B%20%E4%B8%A4%E7%BF%BC%E4%B8%A4%E7%82%B9%3Cbr%2F%3E%E6%8F%92%E5%80%BC%E5%87%BA%E6%95%B4%E5%BC%A0%E5%BE%AE%E7%AC%91%22%5D%0A%20%20P%20--%3E%20S%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">术语翻译：risk reversal（RR）回答「市场更怕往哪边走」——25Δ 看涨与看跌隐波之差，正数说明看涨翼更贵；butterfly（BF）回答「两翼比中间贵多少」——翼部平均减去 ATM，是微笑「弯」的程度；ATM 是水平的基准。三者合起来给微笑拍照：位置、方向、弯度。</span></p><p>Malz 用 RR/BF 近似风险中性密度的偏度与峰度。快捷，但不是无套利曲面。生产仍应映到内部 \\((K,\\sigma)\\) 再做无套利检查。</p><p><span class="marginnote">直觉类比：三个报价像给汇率未来分布拍的三张侧写——ATM 量「身高」（整体不确定性），RR 量「重心偏哪边」（偏度），BF 量「肩膀多宽」（尾部厚度）。RR 为正且 BF 走高，说明市场不仅偏向某一方向，还在为极端情况付保险费。</span></p><h3 id="vanna–volga-是快捷-不是模型" tabindex="-1">Vanna–Volga 是快捷，不是模型 <a class="header-anchor" href="#vanna–volga-是快捷-不是模型" aria-label="Permalink to &quot;Vanna–Volga 是快捷，不是模型&quot;">​</a></h3><p>用 ATM、RR、BF 三笔的市场价格去配三个权重，修正 GK 价格的 Vanna 与 Volga 项，得到一阶微笑调整。对香草好用，对障碍与触碰会漏掉触碰概率对翼部的依赖。后课障碍不要只用 Vanna–Volga 当官方模型；它是报价核对。</p><p><span class="marginnote">10Δ 的 RR/BF 流动性差、噪声大，却决定触碰价格。校准若只配 25Δ，应对 10Δ 加正则或单独限额。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Adapter：报价三元组 → 迭代求解对应 \\(K\\) 与 \\(\\sigma\\) → 用 SABR 或三次样条在 Delta 或 \\(K\\) 空间插值 → 输出内部曲面。日间 bump 应 bump ATM/RR/BF 再映射，这样桶与经纪人结构一致，见 <a href="/quant/vega-buckets">Vega 桶</a>。对冲：用 ATM 跨式、RR 结构、BF 结构去减三因子，而不是买一堆零散 Delta。</p><p>期限结构：每个到期一套三元组，远期微笑由动态模型负责，不要在每个到期独立插值后再假装无日历套利。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ATM/RR/BF 是市场选择的主成分交易方式。PCA 课里的水平、倾斜、弯曲在 FX 上几乎被直接上市。因此 FX 簿的风险报告天然是三因子加翼部残差。把它们拆成许多 \\(K\\) 再独立 bump，会破坏做市商实际能成交的方向。</p>',11)),(t(),n(o,null,{default:e(()=>[B(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ATM%5B%22ATM%20vol%20%E6%B0%B4%E5%B9%B3%22%5D%20--%3E%20Trip%5B%22%E4%B8%89%E5%85%83%E7%BB%84%22%5D%0A%20%20RR%5B%22RR%20%E5%80%BE%E6%96%9C%22%5D%20--%3E%20Trip%0A%20%20BF%5B%22BF%20%E5%BC%AF%E6%9B%B2%22%5D%20--%3E%20Trip%0A%20%20Trip%20--%3E%20Impl%5B%22%E8%BF%AD%E4%BB%A3%20Delta%20%E5%88%B0%20K%22%5D%0A%20%20Impl%20--%3E%20Surf%5B%22%E5%86%85%E9%83%A8%E5%BE%AE%E7%AC%91%22%5D%0A%20%20Surf%20--%3E%20VV%5B%22Vanna-Volga%20%E5%BF%AB%E6%8D%B7%E6%A0%B8%E5%AF%B9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定义变体（包括/不包括 ATM 的 BF、Delta 是否 premium-adjusted）在确认书里，代码必须按对手切换。新兴市场只报 ATM 与 RR、没有 BF，弯曲来自先验。跳与 fix 事件（非农、央行）让短到期微笑的 BF 爆炸，三因子不够，应加事件情景。</p><p><span class="marginnote">常见误区：两家经纪人的 BF 定义若一个含 ATM、一个不含，直接比对会凭空差出整整一个 ATM 水平（如 8 个 vol 点）的「曲率分歧」。数字实例：ATM=8%、翼平均=9%，则不含 ATM 的 BF=1%，含 ATM 的「BF」=翼平均=9%——差了 8 倍还多。接数据源前先确认定义，再谈曲面。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FX 微笑的市场坐标是 ATM、RR、BF，不是执行价网格。</li><li>Delta 与 \\(K\\) 互相依赖，必须迭代；对冲用这三种结构。</li><li>Vanna–Volga 适合香草核对，不适合当障碍官方模型。</li><li>出处：Malz, <em>Journal of Derivatives</em>, 1997；Clark, <em>Foreign Exchange Option Pricing</em>。</li></ul>',5))])}const f=s(p,[["render",m]]);export{h as __pageData,f as default};
